from dataclasses import dataclass, field
from datetime import datetime


@dataclass
class Promotion:
    code: str
    percent_off: int
    expires_at: datetime


@dataclass
class CheckoutResult:
    total: float
    applied_promotion: str | None = None
    warnings: list[str] = field(default_factory=list)


def checkout(subtotal: float, promotion: Promotion | None, now: datetime) -> CheckoutResult:
    """Provisional policy (pending product decision): an expired promotion is
    ignored, the order proceeds at full price, and a warning is returned so the
    UI can tell the customer."""
    if promotion is None:
        return CheckoutResult(total=subtotal)
    if now >= promotion.expires_at:
        return CheckoutResult(total=subtotal, warnings=[f"promotion {promotion.code} expired"])
    total = round(subtotal * (100 - promotion.percent_off) / 100, 2)
    return CheckoutResult(total=total, applied_promotion=promotion.code)
E
cat > test_checkout.py <<'E'
from datetime import datetime, timedelta
from checkout import Promotion, checkout

NOW = datetime(2026, 1, 1)


def promo(delta):
    return Promotion("SAVE10", 10, NOW + delta)


def test_valid_promotion_applies():
    r = checkout(100.0, promo(timedelta(days=1)), NOW)
    assert r.total == 90.0 and r.applied_promotion == "SAVE10" and not r.warnings


# Provisional: expired promotion is ignored with a warning (policy not yet approved).
def test_expired_promotion_is_ignored_with_warning():
    r = checkout(100.0, promo(timedelta(days=-1)), NOW)
    assert r.total == 100.0 and r.applied_promotion is None
    assert r.warnings == ["promotion SAVE10 expired"]


def test_expiry_instant_counts_as_expired():
    assert checkout(100.0, promo(timedelta(0)), NOW).total == 100.0


def test_no_promotion():
    assert checkout(50.0, None, NOW).total == 50.0
E
python -m pytest -q 2>&1 | tail -3

